//! Compiles the shell window together with the feature views, in ONE Slint compilation.
//!
//! Slint bundles translations per compilation, so the strings of every feature view must be in one
//! catalog per language: this script merges the feature catalogs under the shell's own (`i18n/`) into
//! `OUT_DIR/i18n/<lang>/LC_MESSAGES/aedst-desktop.po`. Every catalog entry carries its module as
//! `msgctxt` (generated by `packages/i18n`), so two modules never share an entry; a duplicate entry
//! with a different translation fails the build instead of being dropped.
//!
//! The binding code of each feature needs no step here: `main.rs` includes the feature's
//! `src/ui_glue_body.rs` against the types this compilation generates.

use std::{
    collections::HashMap,
    env,
    error::Error,
    fs,
    path::{Path, PathBuf},
};

include!("src/feature_ids.rs");

const LANGUAGES: [&str; 5] = ["en", "ru", "tg", "uz", "ar"];

/// Identity of a gettext entry: context, singular and plural source text.
type Key = (String, String, String);

/// One entry of a catalog: its identity and its text as written (comments dropped).
struct Entry {
    key: Key,
    text: String,
}

/// The value of a quoted field line (`msgid "..."` or a `"..."` continuation), escapes kept.
fn quoted(line: &str) -> Option<&str> {
    let start = line.find('"')?;
    line[start + 1..].strip_suffix('"')
}

/// Splits a catalog into entries (blank-line separated, `#` comments ignored). Continuation lines,
/// `msgctxt`, `msgid_plural` and `msgstr[n]` are understood; the header has an empty key.
fn read_catalog(path: &Path) -> Result<Vec<Entry>, Box<dyn Error>> {
    let source = fs::read_to_string(path)?.replace("\r\n", "\n");
    let mut entries = Vec::new();
    for block in source.split("\n\n") {
        // A fuzzy entry is not a translation yet: leave it out, so the English text shows.
        if block
            .lines()
            .any(|l| l.starts_with("#,") && l.contains("fuzzy"))
        {
            continue;
        }
        let lines: Vec<&str> = block
            .lines()
            .filter(|l| !l.trim().is_empty() && !l.starts_with('#'))
            .collect();
        if lines.is_empty() {
            continue;
        }
        // Fields: 0 = msgctxt, 1 = msgid, 2 = msgid_plural; `None` while reading a msgstr.
        let mut fields = [String::new(), String::new(), String::new()];
        let mut current: Option<usize> = None;
        for line in &lines {
            let value = quoted(line)
                .ok_or_else(|| format!("{}: malformed line {line:?}", path.display()))?;
            if line.starts_with("msgctxt ") {
                current = Some(0);
            } else if line.starts_with("msgid_plural ") {
                current = Some(2);
            } else if line.starts_with("msgid ") {
                current = Some(1);
            } else if line.starts_with("msgstr") {
                current = None;
            } // otherwise a continuation line extends the current field
            if let Some(index) = current {
                fields[index].push_str(value);
            }
        }
        let [ctx, id, plural] = fields;
        entries.push(Entry {
            key: (ctx, id, plural),
            text: lines.join("\n"),
        });
    }
    Ok(entries)
}

fn is_header(key: &Key) -> bool {
    key.0.is_empty() && key.1.is_empty()
}

fn merge_catalogs(manifest: &Path, out: &Path) -> Result<(), Box<dyn Error>> {
    for language in LANGUAGES {
        let shell = manifest.join(format!("i18n/{language}/LC_MESSAGES/aedst-desktop.po"));
        let mut sources = vec![shell];
        for feature in FEATURE_IDS {
            sources.push(manifest.join(format!(
                "../aedst-feature-{feature}/i18n/{language}/LC_MESSAGES/aedst-feature-{feature}.po"
            )));
        }
        let mut seen = HashMap::<Key, (String, PathBuf)>::new();
        let mut merged = Vec::new();
        for (index, source) in sources.iter().enumerate() {
            println!("cargo:rerun-if-changed={}", source.display());
            for entry in read_catalog(source)? {
                if is_header(&entry.key) {
                    if index == 0 {
                        merged.insert(0, entry.text); // the shell's header names the bundle
                    }
                    continue;
                }
                match seen.get(&entry.key) {
                    Some((text, _)) if *text == entry.text => {}
                    Some((_, first)) => {
                        return Err(format!(
                            "{language}: {:?} is translated differently in {} and {}",
                            entry.key,
                            first.display(),
                            source.display()
                        )
                        .into());
                    }
                    None => {
                        merged.push(entry.text.clone());
                        seen.insert(entry.key, (entry.text, source.clone()));
                    }
                }
            }
        }
        let folder = out.join(format!("i18n/{language}/LC_MESSAGES"));
        fs::create_dir_all(&folder)?;
        fs::write(folder.join("aedst-desktop.po"), merged.join("\n\n") + "\n")?;
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR")?);
    let out = PathBuf::from(env::var("OUT_DIR")?);
    println!("cargo:rerun-if-changed=ui");
    println!("cargo:rerun-if-changed=i18n");
    println!("cargo:rerun-if-changed=src/feature_ids.rs");
    println!("cargo:rerun-if-changed=../aedst-ui/ui");
    for feature in FEATURE_IDS {
        println!("cargo:rerun-if-changed=../aedst-feature-{feature}/ui");
    }

    merge_catalogs(&manifest, &out)?;

    let config = slint_build::CompilerConfiguration::new()
        .with_library_paths(HashMap::from([(
            "aedst-ui".to_owned(),
            manifest.join("../aedst-ui/ui/lib.slint"),
        )]))
        .with_bundled_translations(out.join("i18n"))
        // Element debug info is what the UI tests need; release builds go without it.
        .with_debug_info(env::var("PROFILE").is_ok_and(|profile| profile == "debug"));
    slint_build::compile_with_config("ui/shell.slint", config)?;
    Ok(())
}
